function convertAbsolutePathToWorkspaceRelative(absolutePath) {
    // Split the absolute path into drive letter and relative path
    const [driveLetter, ...relativePath] = absolutePath.split('/');

    // Remove the drive letter if it exists
    if (driveLetter) {
        absolutePath = `file:///` + relativePath.join('/');
    } else {
        absolutePath = `file:///` + absolutePath;
    }

    return absolutePath;
}

