        // Convert the absolute Windows path to a workspace-relative path
        const workspaceRelativePath = convertAbsolutePathToWorkspaceRelative(absolutePath);

        // Replace the absolute Windows path with the workspace-relative path in the markdown link
        markdownLinks[i] = `[[${workspaceRelativePath}]]`;
