// node-uds.js
const { createInterface } = require('readline');
const { readFileSync, writeFileSync } = require('fs');
const { spawn } = require('child_process');

class UnixDatagramSocket {
  constructor(path) {
    this.path = path;
    this.socketFile = `${path}.sock`;
  }

  bind() {
    if (!this.isBound()) {
      try {
        // Create the socket file
        writeFileSync(this.socketFile, '');

        // Start the uds server
        const udsServer = spawn('uds', ['--socket-file', this.socketFile]);

        // Wait for the server to start
        setTimeout(() => {
          if (udsServer.pid) {
            console.log(`Unix datagram socket bound to ${this.path}`);
          } else {
            throw new Error(`Failed to bind Unix datagram socket`);
          }
        }, 1000);
      } catch (error) {
        throw error;
      }
    }

    return this;
  }

  isBound() {
    try {
      const fileContent = readFileSync(this.socketFile, 'utf8');
      return fileContent.length > 0;
    } catch (error) {
      return false;
    }
  }

  send(message) {
    if (!this.isBound()) {
      throw new Error('Unix datagram socket is not bound');
    }

    try {
      // Send the message to the uds server
      const rl = createInterface({
        input: process.stdin,
        output: process.stdout,
      });

      rl.write(`send ${message}\n`);
      rl.close();
    } catch (error) {
      throw error;
    }
  }

  recv() {
    if (!this.isBound()) {
      throw new Error('Unix datagram socket is not bound');
    }

    try {
      // Receive the message from the uds server
      const rl = createInterface({
        input: process.stdin,
        output: process.stdout,
      });

      let message;
      rl.on('line', (line) => {
        if (line.startsWith('recv ')) {
          message = line.substring(5);
          rl.close();
        }
      });
    } catch (error) {
      throw error;
    }

    return message;
  }

  close() {
    try {
      // Close the socket file
      writeFileSync(this.socketFile, '');
    } catch (error) {
      throw error;
    }
  }
}

module.exports = UnixDatagramSocket;

